function CatHouseResultEstimateDialog:InitData()
    local parameters   = self.controller.Argument.parameters
    local myCatData    = parameters.myCatData
    local otherCatData = parameters.otherCatData
    self.myCatData     = myCatData
    self.otherCatData  = otherCatData

    self.catNameList   = self:GetCatNameList(checkNumber(myCatData.catId), checkNumber(otherCatData.catId))

    local geneResultGroupList = {
        [ShowGroupType.Eye]         = {},
        [ShowGroupType.Mouth]       = {},
        [ShowGroupType.Pattern]     = {},
        [ShowGroupType.BodyColor]   = {},
        [ShowGroupType.EarColor]    = {},
        [ShowGroupType.TailColor]   = {},
    }

    local formulaGroupList = {
        [ShowGroupType.Eye]         = {},
        [ShowGroupType.Mouth]       = {},
        [ShowGroupType.Pattern]     = {},
        [ShowGroupType.BodyColor]   = {},
        [ShowGroupType.EarColor]    = {},
        [ShowGroupType.TailColor]   = {},
    }
    
    local id2Res = {}
    local variationFormula       = {}
    local myCatDataGenePartCount = 0
    --- 填充place（1 ~ 6） 数据
    local myCatDataGenes    = myCatData.genes
    for i, geneData in ipairs(myCatDataGenes) do
        ---@type CatHouseCatDataVo
        local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneData.geneId)
        local place    = catDataVo.place
        if geneResultGroupList[place] then
            id2Res[catDataVo.id] = true
            insert(geneResultGroupList[place], catDataVo)
            formulaGroupList[place].myCatGene = catDataVo
        end

        if place == ScreenCatDataSpecifyType.Variation then
            id2Res[catDataVo.id] = true
            insert(variationFormula, catDataVo)
        end

        if catDataVo.kind == ScreenCatDataType.Part then
            myCatDataGenePartCount = myCatDataGenePartCount + 1
        end

    end

    local otherCatDataGenePartCount = 0
    local otherCatDataGenes = otherCatData.genes
    for i, geneData in ipairs(otherCatDataGenes) do
        ---@type CatHouseCatDataVo
        local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneData.geneId)
        local place    = catDataVo.place
        if geneResultGroupList[place] then
            if not id2Res[catDataVo.id] then
                id2Res[catDataVo.id] = true
                insert(geneResultGroupList[place], catDataVo)
            end
            formulaGroupList[place].otherCatGene = catDataVo
        end
        if place == ScreenCatDataSpecifyType.Variation then
            if not id2Res[catDataVo.id] then
                id2Res[catDataVo.id] = true
                insert(variationFormula, catDataVo)
            end
        end

        if catDataVo.kind == ScreenCatDataType.Part then
            otherCatDataGenePartCount = otherCatDataGenePartCount + 1
        end

    end
    
    --- 填充kind为2
    ---@type BaseSetting
    local setting     = CfUtils.GetCf(AutoIds.IdSetting1910, "CatHouseHeritableVo")
    ---@type CatHouseHeritableVo[]
    local heritableVos = setting:GetAll()
    local formulaKey2CombinationGeneId = {}

    for i, heritableVo in ipairs(heritableVos) do
        -- print("formula---------->>>>", table.toString(heritableVo.formula))
        formulaKey2CombinationGeneId[concat(heritableVo.formula)] = heritableVo
    end
    
    local t = {0, 0}
    for showGroupType, data in pairs(formulaGroupList) do
        ---@type CatHouseCatDataVo
        local myCatGene            = data.myCatGene
        local isExistsMyCatGene    = myCatGene ~= nil
        ---@type CatHouseCatDataVo
        local otherCatGene         = data.otherCatGene
        local isExistsOtherCatGene = otherCatGene ~= nil

        local geneGroup = geneResultGroupList[showGroupType]
        if isExistsMyCatGene and isExistsOtherCatGene then
            local myCatGeneId      = myCatGene.id
            local myCatGeneKind    = myCatGene.kind
        
            local otherCatGeneId   = otherCatGene.id
            local otherCatGeneKind = otherCatGene.kind

            local myCatGeneIsBasic          = myCatGeneKind    == ScreenCatDataType.Basic
            local myCatGeneIsCombination    = myCatGeneKind    == ScreenCatDataType.Combination
            local otherCatGeneIsBasic       = otherCatGeneKind == ScreenCatDataType.Basic
            local otherCatGeneIsCombination = otherCatGeneKind == ScreenCatDataType.Combination

            ---两个基础 在添加组合基因
            if myCatGeneIsBasic and otherCatGeneIsBasic then
                t[1], t[2] = myCatGeneId, otherCatGeneId
                local combinationGene = formulaKey2CombinationGeneId[concat(t)]
                t[2], t[1] = myCatGeneId, otherCatGeneId
                combinationGene = combinationGene or formulaKey2CombinationGeneId[concat(t)]
                if combinationGene ~= nil then
                    id2Res[checkNumber(combinationGene.id)] = true
                    --- 两基础变组合 不会出现重复Id 直接插入
                    ---@type CatHouseCatDataVo
                    local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", combinationGene.id)
                    insert(geneGroup, catDataVo)
                end

            ---1基础 1组合 组合拆成基础在与源基础去重
            elseif (myCatGeneIsBasic and otherCatGeneIsCombination) 
                or (myCatGeneIsCombination and otherCatGeneIsBasic)
            then
                
                local basicId          = myCatGeneIsBasic and myCatGeneId or otherCatGeneId
                local combinationId    = myCatGeneIsBasic and otherCatGeneId or myCatGeneId
                ---@type CatHouseHeritableVo
                local heritableVo = CfUtils.GetCfVo(AutoIds.IdSetting1910, "CatHouseHeritableVo", combinationId)
                local formula     = heritableVo.formula
                for i, geneId in ipairs(formula) do
                    if checkNumber(geneId) ~= basicId then
                        id2Res[checkNumber(geneId)] = true
                        ---@type CatHouseCatDataVo
                        local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
                        insert(geneGroup, catDataVo)
                    end
                end

            ---2组合 组合拆成基础去重
            elseif myCatGeneIsCombination and otherCatGeneIsCombination then
                local myCombinationFormula    = CfUtils.GetCfVo(AutoIds.IdSetting1910, "CatHouseHeritableVo", myCatGeneId).formula
                local otherCombinationFormula = CfUtils.GetCfVo(AutoIds.IdSetting1910, "CatHouseHeritableVo", otherCatGeneId).formula
                
                for i, geneId in ipairs(myCombinationFormula) do
                    id2Res[checkNumber(geneId)] = true
                    ---@type CatHouseCatDataVo
                    local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
                    insert(geneGroup, catDataVo)
                end
                for i, geneId in ipairs(otherCombinationFormula) do
                    if not id2Res[checkNumber(geneId)] then
                        id2Res[checkNumber(geneId)] = true
                        ---@type CatHouseCatDataVo
                        local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
                        insert(geneGroup, catDataVo)
                    end
                end
            end

        elseif isExistsMyCatGene or isExistsOtherCatGene then
            --- 只存在一个 则只处理组合 将组合拆为基础 在插入
            ---@type CatHouseCatDataVo
            local catGene     = myCatGene or otherCatGene
            if catGene.kind == ScreenCatDataType.Combination then
                ---@type CatHouseHeritableVo
                local heritableVo = CfUtils.GetCfVo(AutoIds.IdSetting1910, "CatHouseHeritableVo", catGene.id)
                local formula     = heritableVo.formula
                for i, geneId in ipairs(formula) do
                   if not id2Res[checkNumber(geneId)] then
                        id2Res[checkNumber(geneId)] = true
                        ---@type CatHouseCatDataVo
                        local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
                        insert(geneGroup, catDataVo)
                   end

                end

            end
        end


    end

    ---@type BaseSetting
    local setting     = CfUtils.GetCf(AutoIds.IdSetting1911, "CatHouseHeritableVo")
    ---@type CatHouseHeritableVo[]
    heritableVos = setting:GetAll()
    for i, heritableVo in ipairs(heritableVos) do
        local formula = heritableVo.formula
        local len     = #formula
        local count   = len
        for i = 1, len, 1 do
            local geneId = formula[i]
            if id2Res[checkNumber(geneId)] then
                count = count - 1
            end
        end
        if count == 0 and not id2Res[heritableVo.id] then
            ---@type CatHouseCatDataVo
            local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", heritableVo.id)
            insert(variationFormula, catDataVo)
        end
    end

    geneResultGroupList[ShowGroupType.Variation]    = variationFormula
    formulaGroupList[ShowGroupType.Variation] = { text = localize("主题基因不会遗传") }

    local text
    if (myCatDataGenePartCount == 0 or otherCatDataGenePartCount == 0) then
        text = localize("当前极低的概率在出生时获得遗传或随机的部件数据")
    elseif myCatDataGenePartCount >= 1 or otherCatDataGenePartCount >= 1 then
        text = localize("当前较高的概率在出生时获得遗传或随机的部件数据")
    else
        text = localize("当前较低的概率在出生时获得遗传或随机的部件数据")
    end

    geneResultGroupList[ShowGroupType.Part] = {text = text}
    formulaGroupList[ShowGroupType.Part] = {text = text}

    self.formulaGroupList    = formulaGroupList
    self.geneResultGroupList = geneResultGroupList
    -- print("geneResultGroupList",    table.toString(geneResultGroupList))
    -- print("formulaGroupList", table.toString(formulaGroupList))

end

