function CatHouseResultEstimateDialog:FreshUI()
    self:FreshBtnCheckGroupShowState()

    if self.isEnterFormula then
        KTool.SetActive(self.FormulaPanel.gameObject, true)
        KTool.SetActive(self.ResultPanel.gameObject, false)
        self:FreshFormulaPanel()
    else
        KTool.SetActive(self.ResultPanel.gameObject, true)
        KTool.SetActive(self.FormulaPanel.gameObject, false)
        self:FreshResultPanel()
    end

end

function CatHouseResultEstimateDialog:FreshBtnCheckGroupShowState()
    local status = self.isEnterFormula and 2 or 1
    self.BtnCheckGroupImgIcon.Status = status
    self.BtnCheckGroupText.Status    = status
end

