function CatHouseResultEstimateDialog:FreshFormulaPanel()
    if self.panelInitResult[PanelType.Formula] then
        return
    end

    ------------------------
    --- 刷新标题
    local catName = self.catNameList[1]
    self.FormulaMainText.text   = catName
    self.FormulaDeputyText.text = catName

    self:FreshFormulaLayout()

    self.panelInitResult[PanelType.Formula] = true

