--- ResultPanel
---------------------------------------------------

function CatHouseResultEstimateDialog:FreshLayoutPanel(parent, contentNode, contentNodeEnvPath, groupList)
    local tipsNode            = self.CardTipsNode.gameObject
    local child
    local count = 1
    for showGroupType, groupData in ipairs(groupList) do
        local isPart = showGroupType == ShowGroupType.Part
        local child  = isPart and tipsNode or contentNode
        if child then
            local go = parent:AddChild(child)
            go.name = go.name .. count
            count = count + 1
            KTool.SetActive(go.gameObject, true)
            if isPart then
                local textGo = go.transform:Find("Text")
                textGo.gameObject:GetComponent(TextType).text = groupData.text
            else
                self:FreshNodeEnv(go, contentNodeEnvPath, groupData, showGroupType)
            end
        end

    end
end

function CatHouseResultEstimateDialog:FreshNodeEnv(go, envPath, data, showGroupType)
    local env = CfUtils.GetLuaScr(go, envPath)
    if not isNull(env) then
        env:FreshUI(data, ShowGroupType2Name[showGroupType], showGroupType, self.myCatData, self.otherCatData)
    end
end

