function CatHouseResultEstimateDialog:GetCatNameList(myCatId, otherCatId)
    local texts = {}
    ---@type CatHouseCatVo
    local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", myCatId)
    insert(texts, catHouseCatVo.name)
    if myCatId ~= otherCatId then
        ---@type CatHouseCatVo
        local otherCatHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", otherCatId)
        insert(texts, otherCatHouseCatVo.name)
    end
    
    return texts
end

